    async put(owner, name, value) {
      const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
      const aad = enc.encode(secretKey(owner, name));
      const ct = await crypto.subtle.encrypt(
        { name: "AES-GCM", iv, additionalData: aad },
